    27	/**
    28	 * Parses and decodes a query string into an object.
    29	 *
    30	 * The input can be a query string with or without the leading `?`.
    31	 *
    32	 * @example
    33	 *
    34	 * ```js
    35	 * parseQuery("?foo=bar&baz=qux");
    36	 * // { foo: "bar", baz: "qux" }
    37	 *
    38	 * parseQuery("tags=javascript&tags=web&tags=dev");
    39	 * // { tags: ["javascript", "web", "dev"] }
    40	 * ```
    41	 *
    42	 * @note
    43	 * The `__proto__` and `constructor` keys are ignored to prevent prototype pollution.
    44	 *
    45	 * @group Query_utils
    46	 */
    47	export function parseQuery<T extends ParsedQuery = ParsedQuery>(
    48	  parametersString = "",
    49	): T {
    50	  // TODO: Use new EmptyObject() instead of Object.create(null) for better performance in next major version
    51	  // https://github.com/unjs/ufo/pull/290
    52	  const object: ParsedQuery = Object.create(null);
    53	  if (parametersString[0] === "?") {
    54	    parametersString = parametersString.slice(1);
    55	  }
    56	  for (const parameter of parametersString.split("&")) {
    57	    const s = parameter.match(/([^=]+)=?(.*)/) || [];
